// 合并三类来源：YouTube Search、YouTube videos.list statistics、DeepSeek评分。
// 输出：每个视频一条完整标准化记录，适合后续 Supabase 入库。
const searchResponse = $('搜索YouTube').first()?.json || {};
const statsResponse = $('YouTube视频统计').first()?.json || {};
const deepseekResponse = $('HTTP Request').first()?.json || {};

const searchItems = Array.isArray(searchResponse.items) ? searchResponse.items : [];
const statsItems = Array.isArray(statsResponse.items) ? statsResponse.items : [];

const statsByVideoId = new Map(
  statsItems.map(item => [item.id, item])
);

function parseDeepSeekScores(response) {
  const raw = response.choices?.[0]?.message?.content ?? response.content ?? response.text ?? '';
  if (Array.isArray(raw)) return raw;
  if (raw && typeof raw === 'object') return [raw];
  if (typeof raw !== 'string' || !raw.trim()) return [];

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(cleaned);
    return Array.isArray(parsed) ? parsed : [parsed];
  } catch (error) {
    const arrayMatch = cleaned.match(/\[[\s\S]*\]/);
    if (arrayMatch) {
      try {
        const parsed = JSON.parse(arrayMatch[0]);
        return Array.isArray(parsed) ? parsed : [parsed];
      } catch (_) {}
    }
    return [];
  }
}

const scoreItems = parseDeepSeekScores(deepseekResponse);
const scoreByVideoId = new Map(
  scoreItems
    .filter(item => item && item.video_id)
    .map(item => [item.video_id, item])
);

return searchItems.map(item => {
  const videoId = item.id?.videoId || item.id || '';
  const snippet = item.snippet || {};
  const stats = statsByVideoId.get(videoId) || {};
  const statistics = stats.statistics || {};
  const score = scoreByVideoId.get(videoId) || {};

  return {
    json: {
      content_id: `youtube_${videoId}`,
      platform: 'YouTube',
      source: 'YouTube Data API',
      source_url: videoId ? `https://www.youtube.com/watch?v=${videoId}` : '',
      video_id: videoId,
      title: snippet.title || stats.snippet?.title || '无标题',
      description: snippet.description || stats.snippet?.description || '',
      author: snippet.channelTitle || stats.snippet?.channelTitle || '未知作者',
      channel_id: snippet.channelId || stats.snippet?.channelId || '',
      published_at: snippet.publishedAt || stats.snippet?.publishedAt || null,
      thumbnail: snippet.thumbnails?.high?.url || snippet.thumbnails?.default?.url || stats.snippet?.thumbnails?.high?.url || '',
      language: 'en',
      content_type: 'video',
      robotics_topic: 'robotics',
      view_count: Number(statistics.viewCount || 0),
      like_count: Number(statistics.likeCount || 0),
      comment_count: Number(statistics.commentCount || 0),
      favorite_count: Number(statistics.favoriteCount || 0),
      engagement: {
        views: Number(statistics.viewCount || 0),
        likes: Number(statistics.likeCount || 0),
        comments: Number(statistics.commentCount || 0),
        favorites: Number(statistics.favoriteCount || 0),
      },
      viral_score: score.score ?? null,
      ai_summary: score.reason || '暂无评分理由',
      score_source: 'DeepSeek',
      status: 'discovered',
      raw_search_item: item,
      raw_statistics_item: stats,
      raw_deepseek_item: score,
      collected_at: new Date().toISOString(),
    }
  };
});

const raw = $json.choices?.[0]?.message?.content ?? $json.content ?? $json.text ?? '';
function parse(raw) {
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string' || !raw.trim()) return null;
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch (_) {}
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (_) { return null; }
}
function isNonEmptyString(x) { return typeof x === 'string' && x.trim().length > 0; }
function isArray(x) { return Array.isArray(x); }
const parsed = parse(raw);
const sourceItems = $('解析商业分析JSON').all();
const original = sourceItems[$itemIndex]?.json || $json;
const missing = [];
const requiredTop = ['content_id','source_url','editorial_angle','fact_boundary','chinese','english','image_plan','platform_adaptations','commercial_editorial_note','quality_control'];
for (const k of requiredTop) if (!parsed || !Object.prototype.hasOwnProperty.call(parsed,k)) missing.push(k);
if (parsed) {
  for (const k of ['confirmed_facts','inferences','unknowns']) if (!isArray(parsed.fact_boundary?.[k])) missing.push(`fact_boundary.${k}`);
  for (const k of ['title','subtitle','body','hook','discussion_question']) if (!isNonEmptyString(parsed.chinese?.[k])) missing.push(`chinese.${k}`);
  if (!isArray(parsed.chinese?.hashtags)) missing.push('chinese.hashtags');
  if (!isArray(parsed.chinese?.image_overlay_text) || parsed.chinese.image_overlay_text.length < 3) missing.push('chinese.image_overlay_text');
  for (const k of ['title','subtitle','body','hook','discussion_question']) if (!isNonEmptyString(parsed.english?.[k])) missing.push(`english.${k}`);
  if (!isArray(parsed.english?.hashtags)) missing.push('english.hashtags');
  if (!isArray(parsed.english?.image_overlay_text) || parsed.english.image_overlay_text.length < 3) missing.push('english.image_overlay_text');
  if (!isNonEmptyString(parsed.image_plan?.hero_prompt)) missing.push('image_plan.hero_prompt');
  if (!isArray(parsed.image_plan?.info_card_points) || parsed.image_plan.info_card_points.length < 3) missing.push('image_plan.info_card_points');
  if (!isArray(parsed.image_plan?.aspect_ratios) || parsed.image_plan.aspect_ratios.length < 1) missing.push('image_plan.aspect_ratios');
  for (const k of ['linkedin_zh','linkedin_en','youtube_community_zh','youtube_community_en']) if (!isNonEmptyString(parsed.platform_adaptations?.[k])) missing.push(`platform_adaptations.${k}`);
  for (const k of ['x_thread_zh','x_thread_en']) if (!isArray(parsed.platform_adaptations?.[k]) || parsed.platform_adaptations[k].length < 1) missing.push(`platform_adaptations.${k}`);
  for (const k of ['why_now','business_implication','next_question']) if (!isNonEmptyString(parsed.commercial_editorial_note?.[k])) missing.push(`commercial_editorial_note.${k}`);
  if (!isArray(parsed.commercial_editorial_note?.who_should_care) || parsed.commercial_editorial_note.who_should_care.length < 1) missing.push('commercial_editorial_note.who_should_care');
  if (!isNonEmptyString(parsed.quality_control?.copyright_note)) missing.push('quality_control.copyright_note');
  if (!isArray(parsed.quality_control?.fact_check_required)) missing.push('quality_control.fact_check_required');
  if (!isArray(parsed.quality_control?.risk_flags)) missing.push('quality_control.risk_flags');
  if (typeof parsed.quality_control?.ready_for_human_review !== 'boolean') missing.push('quality_control.ready_for_human_review');
}
if (!parsed || missing.length || !isNonEmptyString(parsed?.source_url)) {
  if (!missing.includes('source_url')) missing.push('source_url');
  return { json: { ...original, generation_status: missing.includes('source_url') ? 'blocked_missing_source' : 'blocked_incomplete_draft', missing_fields: [...new Set(missing)], quality_control: { ...(parsed?.quality_control || {}), ready_for_human_review: false } } };
}
return { json: { ...original, ...parsed, generation_status: 'draft_generated', generated_at: new Date().toISOString() } };

const draft = $json;
const qc = draft.quality_control || {};
const hasContent = draft.chinese && draft.english && draft.content_id && !draft.error;
const status = !hasContent
  ? 'failed_missing_bilingual_content'
  : (qc.ready_for_human_review === true ? 'ready_for_review' : 'blocked_fact_check');
return { json: {
  content_id: draft.content_id || null,
  route: 'bilingual_image_text',
  task_type: 'bilingual_social_draft',
  status,
  owner: 'content-agent',
  input_payload: {
    source_url: draft.source_url || null,
    title: draft.title || null,
    language: draft.language || null,
    content_type: draft.content_type || null,
    viral_score: draft.viral_score ?? null,
    view_count: draft.view_count ?? 0,
    like_count: draft.like_count ?? 0,
    comment_count: draft.comment_count ?? 0
  },
  output_payload: draft,
  due_at: null
} };

