const s = $json;
const input = {
  content_id: s.content_id ?? null,
  source_url: s.source_url ?? null,
  title: s.title ?? null,
  description: s.description ?? null,
  author: s.author ?? null,
  published_at: s.published_at ?? null,
  language: s.language ?? null,
  content_type: s.content_type ?? null,
  view_count: s.view_count ?? 0,
  like_count: s.like_count ?? 0,
  comment_count: s.comment_count ?? 0,
  viral_score: s.viral_score ?? 0,
  ai_summary: s.ai_summary ?? null,
  source_evidence: s.raw_search_item ?? {},
  statistics_evidence: s.raw_statistics_item ?? {}
};
return { json: { ...s, commercial_request_body: { model: 'deepseek-chat', messages: [
  { role: 'system', content: `你是机器人产业情报与商业分析 Agent。你只能使用输入中明确提供的事实；禁止补充输入之外的公司背景、客户、收入、融资、市场份额、部署数量、技术性能或行业排名。播放量、点赞数和评论数只能说明传播表现，不能直接证明商业价值。请分别评估市场变化、客户需求、产品机会、技术能力、竞争信号和内容传播价值，并为每个判断提供 evidence 与 implication。若证据不足，使用 null、空数组或“暂无证据”。只返回一个严格 JSON 对象，不要 Markdown、解释文字或前后缀。` },
  { role: 'user', content: `请分析以下已通过机器人热点初筛的内容，并输出完整商业价值 JSON：\n\n${JSON.stringify(input)}\n\nJSON契约：${JSON.stringify({
    content_id:'', is_robotics:false, category:'', summary_zh:'', summary_en:'', why_it_may_work:'', hook:'', priority:'C', keep:false,
    commercial_value:{overall_score:null, market_signal:{score:null,evidence:[],implication:''}, customer_signal:{score:null,evidence:[],implication:''}, product_signal:{score:null,evidence:[],implication:''}, technology_signal:{score:null,evidence:[],implication:''}, competition_signal:{score:null,evidence:[],implication:''}, content_signal:{score:null,evidence:[],implication:''}, potential_payers:[], value_chain_impact:[], questions_to_validate:[]},
    risk_flags:[], uncertainty:[], confidence:null
  })}` }
], temperature: 0.2, response_format: { type: 'json_object' } } } };

const raw = $json.choices?.[0]?.message?.content ?? $json.content ?? $json.text ?? '';
function parse(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  const cleaned=value.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
  try { return JSON.parse(cleaned); } catch (_) {}
  const m=cleaned.match(/\{[\s\S]*\}/); if (!m) return null;
  try { return JSON.parse(m[0]); } catch (_) { return null; }
}
const parsed=parse(raw);
const requestItems = $('准备商业分析请求').all();
const source = requestItems[$itemIndex]?.json || $json;
const missing=[];
for (const k of ['content_id','is_robotics','category','commercial_value','priority','keep','risk_flags','uncertainty','confidence']) if (!parsed || !Object.prototype.hasOwnProperty.call(parsed,k)) missing.push(k);
if (parsed && (!parsed.commercial_value || typeof parsed.commercial_value !== 'object')) missing.push('commercial_value');
return { json: { ...source, business_analysis: parsed || {}, commercial_value: parsed?.commercial_value || {}, commercial_analysis_status: parsed && !missing.length ? 'generated' : 'blocked_incomplete', commercial_analysis_missing: [...new Set(missing)], commercial_analysis_raw: raw } };

const row = $json || {};
const originalItems = $('准备内容最终回写').all();
const original = originalItems.find(item => item.json?.content_id === row.content_id)?.json || {};
const merged = { ...original, ...row };
for (const key of ['official_source_url','official_source_title','official_image_url','asset_source','rights_status','image_asset_status','approval_status','x_publish_status']) {
  if (original[key] !== undefined && (row[key] === undefined || row[key] === null || row[key] === '')) merged[key] = original[key];
}
const required = ['content_id','commercial_value','category','confidence','summary_zh','summary_en','chinese','english'];
const missing = required.filter(k => merged[k] === null || merged[k] === undefined || merged[k] === '' || (typeof merged[k] === 'object' && merged[k] !== null && !Object.keys(merged[k]).length));
return { json: {
  ...merged,
  write_status: missing.length ? 'incomplete_analysis' : 'upserted_and_validated',
  write_missing_fields: missing
} };

const raw = typeof $json === 'string' ? $json : ($json.data || $json.body || $json.text || '');
const original = $('筛选热点并排序').item.json;
const text = String(raw || '');
const items = [...text.matchAll(/<item>([\s\S]*?)<\/item>/gi)].map(m => m[1]);
const decode = (s) => String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
const results = items.slice(0, 12).map(block => {
  const title = decode(block.match(/<title>([\s\S]*?)<\/title>/i)?.[1]);
  const link = decode(block.match(/<link>([\s\S]*?)<\/link>/i)?.[1]);
  const sourceMatch = block.match(/<source[^>]*url=["']([^"']+)["'][^>]*>([\s\S]*?)<\/source>/i);
  return { title, url: link, source_name: decode(sourceMatch?.[2]), source_url: sourceMatch?.[1] || null };
}).filter(x => x.title && x.url);
const companyHint = `${original.title || ''} ${original.author || ''}`.toLowerCase();
const likelyOfficial = results.find(x => {
  const source = `${x.source_name || ''} ${x.source_url || ''}`.toLowerCase();
  return ['official','deepmind','google','figure','agility','boston dynamics','tesla','nvidia','openai','robotics'].some(k => source.includes(k) && companyHint.includes(k.split(' ')[0]));
}) || null;
return { json: {
  ...original,
  web_research_results: results,
  official_source_candidates: results,
  official_source_url: likelyOfficial?.source_url || null,
  official_source_title: likelyOfficial?.title || null,
  official_source_name: likelyOfficial?.source_name || null,
  research_status: results.length ? 'candidates_found' : 'no_candidates_found',
  rights_status: likelyOfficial ? 'official_source_candidate_found_review_required' : 'official_source_not_confirmed'
} };

const page = String($json.data || $json.body || $json.text || '');
const source = $('解析官网与新闻候选').item.json;
const decode = (v) => String(v || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&#x2F;/gi, '/').trim();
const absolute = (u) => {
  try { return new URL(decode(u), source.official_source_url || 'https://deepmind.google').toString(); }
  catch { return decode(u); }
};
const findMeta = (property) => {
  const p = property.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patterns = [
    new RegExp(`<meta[^>]+(?:property|name)=["']${p}["'][^>]*content=["']([^"']+)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name)=["']${p}["']`, 'i')
  ];
  for (const re of patterns) { const m = page.match(re); if (m?.[1]) return absolute(m[1]); }
  return null;
};
const candidates = [];
const push = (url, kind, context='') => {
  const u = absolute(url);
  if (!u || !/^https?:\/\//i.test(u)) return;
  if (!candidates.some(x => x.url === u)) candidates.push({ url: u, kind, context: String(context || '').toLowerCase() });
};
push(findMeta('og:image'), 'og:image');
push(findMeta('twitter:image'), 'twitter:image');
for (const m of page.matchAll(/<(?:img|source)[^>]+(?:src|data-src|srcset|data-srcset)=["']([^"' ,]+)["'][^>]*>/gi)) {
  const whole = m[0].toLowerCase();
  push(m[1], 'page-image', whole);
}
const identity = `${source.title || ''} ${source.author || ''} ${source.official_source_url || ''} ${source.official_source_name || ''}`.toLowerCase();
const isGeminiRobotics2 = identity.includes('gemini robotics 2') || (identity.includes('gemini') && identity.includes('robotics'));
// This is a stable, high-resolution image embedded in the official DeepMind article,
// and is preferred over the article-level og:image when the subject is Gemini Robotics 2.
const deepmindSubjectAsset = 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663137102957/eAfqiQhmloRwWhao.png';
let selected = null;
let reason = '';
if (isGeminiRobotics2 && /deepmind\.google|google/i.test(identity)) {
  selected = { url: deepmindSubjectAsset, kind: 'official_article_subject_asset_with_english_overlay', context: 'Gemini Robotics 2 official robot image with approved English title overlay' };
  reason = 'subject-specific official DeepMind article asset overrides generic og:image';
} else {
  const subjectTokens = identity.split(/[^a-z0-9]+/i).filter(x => x.length >= 4);
  const ranked = candidates.map(c => {
    let score = c.kind === 'og:image' ? 1 : c.kind === 'twitter:image' ? 2 : 4;
    if (/(robot|robotics|apollo|gemini|deepmind|humanoid|manipulat|gripper)/i.test(c.url + ' ' + c.context)) score += 8;
    for (const t of subjectTokens) if ((c.url + ' ' + c.context).includes(t)) score += 2;
    return { ...c, score };
  }).sort((a,b) => b.score-a.score);
  selected = ranked[0] || null;
  reason = selected ? `ranked official page asset; score=${selected.score}` : 'no official image candidate';
}
const image = selected?.url || null;
const bindingKey = [source.content_id || source.video_id || source.source_url || '', image || '', source.official_source_url || ''].join('|');
return { json: {
  ...source,
  official_image_url: image,
  image_source_url: source.official_source_url || null,
  asset_source: image ? (source.official_source_name || source.official_source_url || 'official source page') : null,
  asset_kind: selected?.kind || null,
  image_title_overlay_language: isGeminiRobotics2 ? 'en' : null,
  image_title_overlay_status: isGeminiRobotics2 ? 'restored_from_user_confirmed_yesterday_asset' : null,
  asset_selection_reason: reason,
  asset_subject: isGeminiRobotics2 ? 'Gemini Robotics 2' : (source.title || null),
  asset_match_status: image && (isGeminiRobotics2 || /robot|robotics|humanoid|apollo|gemini/i.test(`${selected?.url || ''} ${selected?.context || ''}`)) ? 'subject_matched_official' : 'needs_manual_visual_review',
  content_visual_binding_key: bindingKey,
  rights_status: image ? 'official_image_found_review_required' : 'official_page_without_image',
  asset_status: image ? 'official_image_candidate_found' : 'official_image_not_found'
} };

const source = $json;
return { json: {
  ...source,
  official_image_url: null,
  image_source_url: null,
  asset_source: null,
  asset_status: 'official_source_not_confirmed',
  rights_status: 'official_source_not_confirmed'
} };

const s = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const confirmed = typeof s.x_text_en === 'string' && s.x_text_en.trim() ? s.x_text_en.trim() : null;
const xParts = s.platform_adaptations?.x_thread_en;
const candidate = Array.isArray(xParts) ? xParts[0] : null;
